<template>
<AdminLayout><div class="container mx-auto px-3 py-6 md:px-6"><div class="mb-6 flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-3xl font-semibold text-slate-800">Repartidores</h1><p class="text-sm text-slate-500">Personal habilitado para reparto propio</p></div><button class="min-h-11 rounded-lg bg-blue-600 px-4 font-semibold text-white" @click="open()"><i class="pi pi-plus mr-2"/>Nuevo repartidor</button></div><input v-model="search" class="mb-4 min-h-11 w-full rounded-lg border p-3 md:w-96" placeholder="Buscar por código, nombre o documento" @input="load"><div v-if="loading" class="rounded-xl bg-white p-10 text-center">Cargando repartidores…</div><div v-else class="grid gap-4 lg:grid-cols-2"><article v-for="item in items" :key="item.id" class="rounded-xl border bg-white p-5 shadow-sm"><div class="flex justify-between gap-3"><div><span class="font-mono text-xs text-slate-500">{{item.code}}</span><h2 class="text-lg font-bold">{{item.first_name}} {{item.last_name}}</h2><p class="text-sm text-slate-600">{{masked(item.document_number)}} · {{item.phone}}</p></div><span class="rounded-full px-2 py-1 text-xs font-semibold" :class="item.is_active?'bg-emerald-100 text-emerald-700':'bg-slate-200 text-slate-600'">{{item.is_active?(item.is_available?'Disponible':'No disponible'):'Inactivo'}}</span></div><div class="mt-4 grid grid-cols-2 gap-2 text-sm"><div class="rounded bg-slate-50 p-3">{{item.active_deliveries_count||0}} entrega activa</div><div class="rounded bg-slate-50 p-3">{{item.deliveries_count||0}} entregas totales</div></div><div class="mt-4 flex justify-end gap-2 border-t pt-3"><button class="rounded px-3 py-2 text-blue-700" @click="open(item)"><i class="pi pi-pencil"/></button><button class="rounded px-3 py-2 text-sm" :class="item.is_available?'text-amber-700':'text-emerald-700'" :disabled="!item.is_active" @click="toggleAvailability(item)">{{item.is_available?'Marcar no disponible':'Marcar disponible'}}</button><button class="rounded px-3 py-2 text-sm text-red-700" @click="toggleActive(item)">{{item.is_active?'Desactivar':'Activar'}}</button></div></article><div v-if="!items.length" class="rounded-xl bg-white p-10 text-center text-slate-500 lg:col-span-2">No hay repartidores registrados.</div></div><div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-3"><form class="max-h-[94vh] w-full max-w-2xl overflow-y-auto rounded-xl bg-white p-6" @submit.prevent="save"><div class="mb-5 flex justify-between"><h2 class="text-xl font-bold">{{form.id?'Editar':'Nuevo'}} repartidor</h2><button type="button" class="text-2xl" @click="modal=false">&times;</button></div><div class="grid gap-3 md:grid-cols-2"><label>Código<input v-model="form.code" required class="field"></label><label>Teléfono<input v-model="form.phone" required class="field"></label><label>Nombres<input v-model="form.first_name" required class="field"></label><label>Apellidos<input v-model="form.last_name" required class="field"></label><label>Tipo documento<input v-model="form.document_type" class="field"></label><label>Número documento<input v-model="form.document_number" class="field"></label><label>Correo<input v-model="form.email" type="email" class="field"></label><label>Licencia<input v-model="form.license_number" class="field"></label><label>Categoría licencia<input v-model="form.license_category" class="field"></label><label>Vence licencia<input v-model="form.license_expires_at" type="date" class="field"></label><label class="md:col-span-2">Notas<textarea v-model="form.notes" class="field"/></label><label class="flex gap-2"><input v-model="form.is_active" type="checkbox"> Activo</label><label class="flex gap-2"><input v-model="form.is_available" type="checkbox"> Disponible</label></div><div class="mt-5 flex justify-end gap-3"><button type="button" class="rounded bg-slate-100 px-4 py-2" @click="modal=false">Cancelar</button><button class="rounded bg-blue-600 px-4 py-2 font-semibold text-white" :disabled="saving">Guardar</button></div></form></div></div></AdminLayout>
</template>
<script setup>
import {onMounted,ref} from 'vue';import AdminLayout from '@/layouts/AdminLayout.vue';import api from '@/api';import {useToast} from 'primevue/usetoast';
const toast=useToast(),items=ref([]),search=ref(''),loading=ref(false),modal=ref(false),saving=ref(false),form=ref({});let timer;const empty=()=>({code:'',first_name:'',last_name:'',phone:'',document_type:'DNI',document_number:'',email:'',license_number:'',license_category:'',license_expires_at:'',notes:'',is_active:true,is_available:true});const message=e=>e.response?.data?.message||Object.values(e.response?.data?.errors||{})[0]?.[0]||'No se pudo completar la operación.';const masked=v=>v?v.length>4?'*'.repeat(v.length-4)+v.slice(-4):v:'Sin documento';function load(){clearTimeout(timer);timer=setTimeout(async()=>{loading.value=true;try{items.value=(await api.get('/admin/delivery-drivers',{params:{search:search.value}})).data.data}catch(e){toast.add({severity:'error',summary:'Error',detail:message(e),life:4000})}finally{loading.value=false}},150)}function open(item=null){form.value=item?{...item}:empty();modal.value=true}async function save(){saving.value=true;try{form.value.id?await api.put(`/admin/delivery-drivers/${form.value.id}`,form.value):await api.post('/admin/delivery-drivers',form.value);modal.value=false;load()}catch(e){toast.add({severity:'error',summary:'No se pudo guardar',detail:message(e),life:5000})}finally{saving.value=false}}async function toggleActive(item){try{await api.patch(`/admin/delivery-drivers/${item.id}/status`,{is_active:!item.is_active});load()}catch(e){toast.add({severity:'warn',summary:'Operación rechazada',detail:message(e),life:4000})}}async function toggleAvailability(item){try{await api.patch(`/admin/delivery-drivers/${item.id}/availability`,{is_available:!item.is_available});load()}catch(e){toast.add({severity:'warn',summary:'Operación rechazada',detail:message(e),life:4000})}}onMounted(load);
</script><style scoped>.field{@apply mt-1 block min-h-11 w-full rounded-lg border border-slate-300 p-2}</style>
